steps.script:
var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.setup(1, "Emissaries Imperatus", {"flags": {"U_MEGANOBZ_A": {"cus11e_katah_kaptaris": true}}})

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
PhaseManager.transition_to_phase(10)
return int(GameState.get_current_phase())

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.window_id()

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.decider()

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return main.get_tree().root.get_node("StratagemDialog/Content/Header").text.to_lower().contains("selected to fight")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.flag("U_CONTEMPTOR_A", "cus11e_bearers_of_his_light")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return (H.codex().apply_hit_bits(H.codex().HIT_MINUS_ONE, H.unit("U_CONTEMPTOR_A"), H.unit("U_MEGANOBZ_A"), true, GameState.state, []) & H.codex().HIT_MINUS_ONE) == 0

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return (H.codex().apply_wound_bits(H.codex().WOUND_MINUS_ONE, H.unit("U_CONTEMPTOR_A"), H.unit("U_MEGANOBZ_A"), true, 6, 6, []) & H.codex().WOUND_MINUS_ONE) == 0

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return H.log_count("Used BEARERS OF HIS LIGHT")

var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
return "U_CONTEMPTOR_A" in H.phase().units_that_fought
